const SUFFIXES = ["_pos_pct", "_conf_pct", "_rank", "_pct", "_n"];
const PHASES: MetricPhase[] = ["pass", "rush"];
const SIDES: MetricSide[] = ["off", "def", "margin"];
type PhaseWords = Record<MetricPhase, [string, Record<string, string>]>;
const LABEL_WORDS: PhaseWords = { pass: ["Pass", { Play: "Dropback", Plays: "Dropbacks" }], rush: ["Rush", { Play: "Rush", Plays: "Rushes" }] };
const SHORT_WORDS: PhaseWords = { pass: ["Pass", { Play: "DB", Plays: "Dropbacks" }], rush: LABEL_WORDS.rush };
const has = (key: string): boolean => Object.prototype.hasOwnProperty.call(METRICS, key);
// only the adjusted columns spell their side as a prefix / infix (adj_off_epa, off_strength_faced, net_adj_epa)
const adjusted = (key: string): boolean => has(key) && METRICS[key].family === "adjusted";

function phased(text: string, phase: MetricPhase | undefined, words: PhaseWords): string {
    if (!phase) return text;
    const [prefix, swap] = words[phase];
    if (/\bPlays?\b/.test(text)) return text.replace(/\bPlays?\b/g, (m) => swap[m]);
    return text.startsWith(prefix) ? text : `${prefix} ${text}`;
}

function split(column: string): [string, MetricSide | undefined, MetricPhase | undefined, string | undefined] | null {
    // the exact column first, so a registered X_pct is never read as X + _pct
    for (const suffix of [undefined, ...SUFFIXES]) {
        if (suffix !== undefined && !column.endsWith(suffix)) continue;
        let stem = suffix ? column.slice(0, -suffix.length) : column;
        const phase = PHASES.find((p) => stem.endsWith(`_${p}`));
        if (phase) stem = stem.slice(0, -phase.length - 1);
        const side = SIDES.find((s) => stem.endsWith(`_${s}`));
        if (side) stem = stem.slice(0, -side.length - 1);
        if (has(stem)) return [stem, side, phase, suffix];
        if (!side && !phase) {
            const net = /^net_(.+)$/.exec(stem);
            if (net && adjusted(net[1])) return [net[1], "margin", undefined, suffix];
            const infix = /^(?:(.+)_)?(off|def)_(.+)$/.exec(stem);
            if (infix) {
                const base = infix[1] ? `${infix[1]}_${infix[3]}` : infix[3];
                if (adjusted(base)) return [base, infix[2] as MetricSide, undefined, suffix];
            }
        }
    }
    return null;
}

/** The entry behind a published column, or null. `_def` flips the polarity; a `_margin` is always higher-is-better. */
export function resolveMetric(column: string): ResolvedMetric | null {
    const found = split(column);
    if (!found) return null;
    const [key, side, phase, suffix] = found;
    const entry = METRICS[key];
    let polarity: Polarity = entry.polarity;
    if (side === "def") polarity = polarity === "higher" ? "lower" : "higher";
    else if (side === "margin") polarity = "higher";
    const out: ResolvedMetric = {
        ...entry,
        variants: { ...entry.variants },
        label: phased(entry.label, phase, LABEL_WORDS),
        short: phased(entry.short, phase, SHORT_WORDS),
        polarity,
    };
    if (side) out.side = side;
    if (phase) out.phase = phase;
    if (suffix) out.suffix = suffix;
    return out;
}
